<template><div class="screen"><main><header><button @click="$router.back()"><span class="material-symbols-outlined">arrow_forward</span></button><h1>البيانات الشخصية</h1></header><div class="steps"><span v-for="(x,i) in labels" :class="{on:step===i+1,done:step>i+1}" :key="x"><b>{{i+1}}</b>{{x}}</span></div><section v-if="step===1"><h2>المعلومات الشخصية</h2><Field v-model="f.fullName" icon="person" text="الاسم الكامل"/><Field v-model="f.phone" icon="phone" text="رقم الهاتف"/><Field v-model="f.nationalId" icon="badge" text="رقم البطاقة الوطنية"/><label class="field"><span class="material-symbols-outlined">calendar_month</span><input v-model="f.birthDate" type="date"/></label><Field v-model="f.address" icon="location_on" text="العنوان"/><Field v-model="f.password" icon="lock" text="كلمة المرور" type="password"/><button class="primary" @click="next">التالي</button></section><section v-else-if="step===2"><h2>المعلومات الوظيفية</h2><div class="types"><button :class="{on:f.type==='government'}" @click="f.type='government'">موظف حكومي</button><button :class="{on:f.type==='private'}" @click="f.type='private'">قطاع خاص</button></div><template v-if="f.type==='government'"><Field v-model="f.department" icon="domain" text="اسم الدائرة"/><Field v-model="f.jobTitle" icon="work" text="المسمى الوظيفي"/></template><template v-else><Field v-model="f.profession" icon="work" text="المهنة"/><Field v-model="f.workplace" icon="business" text="جهة العمل"/><Field v-model="f.activityName" icon="storefront" text="اسم النشاط"/></template><button class="primary" @click="next">التالي</button><button class="back" @click="step=1">رجوع</button></section><section v-else><h2>المستمسكات</h2><div class="photo"><div class="avatar"><img v-if="preview" :src="preview"/><span v-else class="material-symbols-outlined">person</span></div><div><b>الصورة الشخصية</b><small>التقاط حي أو من الهاتف</small><div class="choices"><label><input type="file" accept="image/*" capture="user" @change="profile"/>التقاط</label><label><input type="file" accept="image/*" @change="profile"/>من الهاتف</label></div></div></div><RegistrationDocumentCard title="البطاقة الوطنية - الوجه الأمامي" icon="credit_card" :file="f.nationalFront" @change="x=>file(x,'nationalFront')"/><RegistrationDocumentCard title="البطاقة الوطنية - الوجه الخلفي" icon="credit_card" :file="f.nationalBack" @change="x=>file(x,'nationalBack')"/><RegistrationDocumentCard title="بطاقة السكن" icon="home" :file="f.residenceCard" @change="x=>file(x,'residenceCard')"/><RegistrationDocumentCard v-if="f.type==='government'" title="هوية الدائرة (اختيارية)" icon="badge" :file="f.departmentId" @change="x=>file(x,'departmentId')"/><label class="agree"><input v-model="agreed" type="checkbox"/> أوافق على شروط الاستخدام وسياسة الخصوصية</label><button class="primary" :disabled="!agreed" @click="save">حفظ التعديلات</button><button class="back" @click="step=2">رجوع</button></section></main></div></template>
<script setup>import{defineComponent,h,reactive,ref}from'vue';import{useRouter}from'vue-router';import RegistrationDocumentCard from'../components/RegistrationDocumentCard.vue';const router=useRouter(),step=ref(1),agreed=ref(true),preview=ref(null),labels=['المعلومات الشخصية','المعلومات الوظيفية','المستمسكات'],u=JSON.parse(localStorage.getItem('golden_user')||'{}'),f=reactive({fullName:u.fullName||'',phone:u.phone||'',nationalId:u.nationalId||'',birthDate:u.birthDate||'',address:u.address||'',password:'',type:u.clientType||'government',department:u.department||'',jobTitle:u.jobTitle||'',profession:u.profession||'',workplace:u.workplace||'',activityName:u.activityName||'',profilePhoto:null,nationalFront:null,nationalBack:null,residenceCard:null,departmentId:null});preview.value=u.profilePhoto||null;const Field=defineComponent({props:['modelValue','icon','text','type'],emits:['update:modelValue'],setup(p,{emit}){return()=>h('label',{class:'field'},[h('span',{class:'material-symbols-outlined'},p.icon),h('input',{type:p.type||'text',placeholder:p.text,value:p.modelValue,onInput:e=>emit('update:modelValue',e.target.value)})])}});const next=()=>{if(step.value===1&&(!f.fullName||!f.phone||!f.nationalId||!f.birthDate||!f.address||!f.password))return;if(step.value===2&&((f.type==='government'&&(!f.department||!f.jobTitle))||(f.type==='private'&&(!f.profession||!f.workplace||!f.activityName))))return;step.value++};const file=(x,k)=>f[k]=x,profile=e=>{let x=e.target.files?.[0];if(x){f.profilePhoto=x;preview.value=URL.createObjectURL(x)}};const save=()=>{if(!f.profilePhoto||!f.nationalFront||!f.nationalBack||!f.residenceCard)return;localStorage.setItem('golden_user',JSON.stringify({...f,profilePhoto:preview.value}));router.push('/account')}</script>
<style scoped>.screen{min-height:100dvh;background:var(--bg)}main{max-width:420px;margin:auto;padding:0 20px 36px}header{position:sticky;top:0;z-index:5;height:60px;margin:0 -20px 12px;display:grid;place-items:center;background:var(--bg);border-bottom:1px solid rgba(196,154,59,.35)}h1,h2{margin:0;color:var(--on-surface)}h1{font-size:19px}h2{font-size:17px}header button{position:absolute;right:12px;border:0;background:none;color:var(--on-surface)}.steps{display:grid;grid-template-columns:repeat(3,1fr);margin:4px 0 22px}.steps span{display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--on-surface-variant);font-size:10px}.steps b{display:grid;place-items:center;width:28px;height:28px;border:1px solid var(--outline-variant);border-radius:50%}.steps .on,.steps .done{color:var(--primary)}.steps .on b,.steps .done b{border-color:var(--primary)}section{display:flex;flex-direction:column;gap:12px}.field{display:flex;align-items:center;height:53px;padding:0 13px;border:1px solid rgba(196,154,59,.25);border-radius:13px;background:var(--surface-container-high)}.field span{margin-left:9px;color:var(--primary)}.field input{flex:1;border:0;outline:0;background:none;color:var(--on-surface);font:inherit}.types{display:grid;grid-template-columns:1fr 1fr;gap:10px}.types button{padding:14px;border:1px solid var(--outline-variant);border-radius:13px;background:var(--surface-container-high);color:var(--on-surface);font:inherit}.types .on{border-color:var(--primary);color:var(--primary)}.primary,.back{height:50px;border:0;border-radius:13px;font:800 14px inherit}.primary{background:var(--primary);color:#101522}.back{height:42px;background:none;border:1px solid var(--outline-variant);color:var(--on-surface)}.photo{display:flex;align-items:center;gap:12px;padding:13px;border:1px solid rgba(196,154,59,.28);border-radius:17px;background:linear-gradient(135deg,rgba(196,154,59,.08),var(--surface-container))}.avatar{width:72px;height:72px;display:grid;place-items:center;overflow:hidden;border-radius:50%;background:var(--surface-container-high);color:var(--primary)}.avatar img{width:100%;height:100%;object-fit:cover}.photo b{display:block;color:var(--on-surface);font-size:12px}.photo small{display:block;margin-top:3px;color:var(--on-surface-variant);font-size:10px}.choices{display:flex;gap:7px;margin-top:8px}.choices label{padding:6px 8px;border:1px solid rgba(196,154,59,.36);border-radius:9px;color:var(--primary);font-size:10px}.choices input{display:none}.agree{font-size:11px;color:var(--on-surface)}</style>
